type Ctx = { lang: Lang; setLang: (l: Lang) => void };
const LangCtx = createContext<Ctx>({ lang: "en", setLang: () => {} });
export const useLang = () => useContext(LangCtx);

function translateDom(lang: Lang) {
  if (typeof document === "undefined") return;
  const root = document.body;
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = (node as Text).parentElement;
      if (!parent) return NodeFilter.FILTER_REJECT;
      const tag = parent.tagName;
      if (tag === "SCRIPT" || tag === "STYLE" || tag === "NOSCRIPT") return NodeFilter.FILTER_REJECT;
      if (parent.closest("[data-no-translate]")) return NodeFilter.FILTER_REJECT;
      if (!node.nodeValue || !node.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    },
  });
  const nodes: Text[] = [];
  let n = walker.nextNode();
  while (n) {
    nodes.push(n as Text);
    n = walker.nextNode();
  }
  /* Attributes the reader actually sees. The tree walker only visits text
     nodes, so placeholders and tooltips stayed English in every language until
     they were handled explicitly here. */
  const ATTRS = ["placeholder", "title", "aria-label"] as const;
  for (const el of Array.from(root.querySelectorAll<HTMLElement>("[placeholder],[title],[aria-label]"))) {
    if (el.closest("[data-no-translate]")) continue;
    for (const attr of ATTRS) {
      const cur = el.getAttribute(attr);
      if (!cur) continue;
      const store = `__en_${attr}`;
      const bag = el as HTMLElement & Record<string, string | undefined>;
      if (bag[store] === undefined) bag[store] = cur;
      const original = bag[store] as string;
      if (lang === "en") {
        if (cur !== original) el.setAttribute(attr, original);
        continue;
      }
      const t = DICT[original.trim()]?.[lang];
      if (t && cur !== t) el.setAttribute(attr, t);
      else if (!t && cur !== original) el.setAttribute(attr, original);
    }
  }

  for (const node of nodes) {
    // stash the original English once
    const el = node as Text & { __en?: string };
    if (el.__en === undefined) el.__en = node.nodeValue ?? "";
    const original = el.__en;
    const key = original.trim();
    if (lang === "en") {
      if (node.nodeValue !== original) node.nodeValue = original;
      continue;
    }
    const row = DICT[key];
    const translated = row?.[lang];
    if (translated) {
      // preserve surrounding whitespace
      const lead = original.match(/^\s*/)?.[0] ?? "";
      const trail = original.match(/\s*$/)?.[0] ?? "";
      const next = lead + translated + trail;
      if (node.nodeValue !== next) node.nodeValue = next;
    } else if (node.nodeValue !== original) {
      node.nodeValue = original;
    }
  }
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("en");
  const timers = useRef<number[]>([]);

  const apply = useCallback((l: Lang) => {
    const html = document.documentElement;
    html.lang = l;
    html.dir = RTL.includes(l) ? "rtl" : "ltr";
    translateDom(l);
    // late re-passes catch content that renders/animates in after the switch
    timers.current.forEach(clearTimeout);
    timers.current = [300, 900, 1800].map((ms) => window.setTimeout(() => translateDom(l), ms));
  }, []);

  const setLang = useCallback(
    (l: Lang) => {
      setLangState(l);
      try {
        localStorage.setItem("elsiaa_lang", l);
      } catch {
        /* noop */
      }
      apply(l);
    },
    [apply],
  );

  // restore saved language on mount
  useEffect(() => {
    let saved: Lang | null = null;
    try {
      saved = localStorage.getItem("elsiaa_lang") as Lang | null;
    } catch {
      /* noop */
    }
    if (saved && LANGS.some((x) => x.code === saved) && saved !== "en") {
      setLangState(saved);
      apply(saved);
    }
  }, [apply]);

  // re-translate on client-side route changes (history navigation)
  useEffect(() => {
    if (lang === "en") return;
    const onNav = () => {
      timers.current.forEach(clearTimeout);
      timers.current = [80, 400, 1000].map((ms) => window.setTimeout(() => translateDom(lang), ms));
    };
    window.addEventListener("popstate", onNav);
    const origPush = history.pushState;
    history.pushState = function (...args) {
      const r = origPush.apply(this, args as Parameters<typeof history.pushState>);
      onNav();
      return r;
    };
    return () => {
      window.removeEventListener("popstate", onNav);
      history.pushState = origPush;
    };
  }, [lang]);

  return <LangCtx.Provider value={{ lang, setLang }}>{children}</LangCtx.Provider>;
}
